func TestResolveRef(t *testing.T) {
	env := map[string]any{
		"req":        map[string]any{"exam_id": "1", "student_id": "3"},
		"now":        "2026-05-21T10:00:00Z",
		"assignment": []map[string]any{{"class_id": "3", "max_attempts": float64(2)}},
	}
	cases := []struct{ in, want string }{
		{"$req.exam_id", "1"},
		{"$req.student_id", "3"},
		{"$now", "2026-05-21T10:00:00Z"},
		{"$assignment.0.class_id", "3"},
		{"$assignment.0.max_attempts", "2"},
		{"$assignment.5.class_id", ""},
		{"$missing.0.x", ""},
		{"$req.nope", ""},
		{"literal", "literal"},
		{"42", "42"},
	}
	for _, c := range cases {
		if got := resolveRef(c.in, env); got != c.want {
			t.Errorf("resolveRef(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

