func TestBuildSearch(t *testing.T) {
	env := map[string]any{
		"req":        map[string]any{"exam_id": "7", "status": "ACTIVE"},
		"assignment": []map[string]any{{"class_id": "9"}},
	}
	where := []Criteria{
		{Field: "exam_id", Op: "EQUAL", Value: "$req.exam_id"},
		{Logic: "OR", Group: []Criteria{
			{Field: "class_id", Op: "EQUAL", Value: "$assignment.0.class_id"},
			{Field: "status", Op: "EQUAL", Value: "$req.status"},
		}},
	}
	s := buildSearch(where, env)
	if len(s.GetFilters()) != 2 {
		t.Fatalf("want 2 top-level filters, got %d", len(s.GetFilters()))
	}
	// leaf condition
	c0 := s.GetFilters()[0].GetCondition()
	if c0.GetField() != "exam_id" || c0.GetValues()[0] != "7" {
		t.Errorf("filter0 = %q / %v", c0.GetField(), c0.GetValues())
	}
	// nested OR group
	g := s.GetFilters()[1].GetGroup()
	if g == nil {
		t.Fatal("filter1 should be a group, not a condition")
	}
	if g.GetLogic() != commonpb.LogicalCondition_OR {
		t.Errorf("group logic = %v, want OR", g.GetLogic())
	}
	if len(g.GetFilters()) != 2 {
		t.Fatalf("group should have 2 filters, got %d", len(g.GetFilters()))
	}
	if g.GetFilters()[0].GetCondition().GetValues()[0] != "9" {
		t.Errorf("group filter0 value = %v, want [9] (resolved $assignment.0.class_id)",
			g.GetFilters()[0].GetCondition().GetValues())
	}
}

